        [29801]={questID=29801,name="Proving Your Worth",pickup={mapID=409,x=0.502,y=0.596},instructions="On a Rogue, take Proving Your Worth in original Dragon Soul on Normal or Heroic. Progress to Hagara, STEALTH and PICK POCKET her for the Cryptomancer's Decoder Ring BEFORE killing her. Raid Finder does not supply the legendary items. Return to the quest giver inside the raid.",requires={},sourceURL="https://www.wowhead.com/quest=29801",classes={4},npcID=55476,turnIn={mapID=409,x=0.502,y=0.596},objective={mapID=412,x=0.5275,y=0.5205}},
        [29802]={questID=29802,name="A Hidden Message",pickup={mapID=409,x=0.502,y=0.596},instructions="Take the decoder ring to Thaumaturge Rafir in Stormwind (50.6,61.3) or Altha in Orgrimmar (57.6,65.5), pay 10,000 gold and wait twelve real hours for its charge. Use the charged ring at the egg near Corastrasza, Twilight Highlands 29,25, then report to her. Do not confuse the charge timer with a daily reset.",requires={29801},sourceURL="https://www.wowhead.com/quest=29802",classes={4},npcID=55476,turnIn={mapID=241,x=0.29,y=0.25},objectiveByFaction={Alliance={mapID=84,x=0.506,y=0.613},Horde={mapID=85,x=0.5760000000000001,y=0.655}},objectiveReference=true},
        [29847]={questID=29847,name="To Catch a Thief",pickup={mapID=25,x=0.6779999999999999,y=0.452},instructions="Infiltrate Ravenholdt Manor and locate the missing black dragon egg.\n\nRequirements:\n - Egg Located",requires={29934},sourceURL="https://www.wowhead.com/quest=29847",classes={4},npcID=56375,turnIn={mapID=25,x=0.7140000000000001,y=0.456},objectiveReference=true},
