        [30092]={questID=30092,name="Our Man in Gilneas",pickup={mapID=25,x=0.7140000000000001,y=0.456},instructions="Seek out Zazzo Twinklefingers near the ruins of Gilneas City in Gilneas.",requires={29847},sourceURL="https://www.wowhead.com/quest=30092",classes={4},npcID=57777,turnIn={mapID=42,x=0.526,y=0.7759999999999999},objectiveReference=true},
        [30093]={questID=30093,name="Assassinate Creed",pickup={mapID=42,x=0.526,y=0.7759999999999999},instructions="Stealth into the ruins of Gilneas City and slay Hiram Creed within the military district.\n\nRequirements:\n - Lord Hiram Creed",requires={30092},sourceURL="https://www.wowhead.com/quest=30093",classes={4},npcID=57770,turnIn={mapID=42,x=0.526,y=0.7759999999999999},objective={mapID=217,x=0.644,y=0.56}},
