        [30107]={questID=30107,name="Cluster Clutch",pickup={mapID=25,x=0.7140000000000001,y=0.456},instructions="Loot Elementium Gem Clusters from original Normal/Heroic Dragon Soul bosses and OPEN them for 333 Shadowy Gems. Prefer 25-player mode for cluster supply. Normal and Heroic share this raid's weekly boss lockout. Stop opening clusters when the gem target is met and keep spare INTACT clusters for the later sixty-cluster stage.",requires={30106},sourceURL="https://www.wowhead.com/quest=30107",classes={4},npcID=57777,turnIn={mapID=25,x=0.7140000000000001,y=0.456},objective={mapID=71,x=0.644,y=0.5}},
        [30108]={questID=30108,name="Our Man in Karazhan",pickup={mapID=25,x=0.7140000000000001,y=0.456},instructions="Report to Zazzo Twinklefingers in the ruins just southeast of Karazhan.",requires={30107},sourceURL="https://www.wowhead.com/quest=30108",classes={4},npcID=57777,turnIn={mapID=42,x=0.526,y=0.7759999999999999},objectiveReference=true},
        [30109]={questID=30109,name="Blood of the Betrayer",pickup={mapID=42,x=0.526,y=0.7759999999999999},instructions="Meet Zazzo at the original Karazhan approach and enter the special cellar mission. Sneak through its patrols and defeat Nalice using the quest mechanics, then return to Ravenholdt. The outdoor marker is the cellar approach, not an exact location for Nalice in her separate scenario.",requires={30108},sourceURL="https://www.wowhead.com/quest=30109",classes={4},npcID=57770,turnIn={mapID=42,x=0.526,y=0.7759999999999999},objective={mapID=42,x=0.47,y=0.75},objectiveReference=true},
        [30113]={questID=30113,name="Victory in the Depths",pickup={mapID=42,x=0.526,y=0.7759999999999999},instructions="Take the Vial of Preserved Dragonsblood, along with your daggers Fear and Vengeance, to Wrathion at Ravenholdt Manor in Hillsbrad Foothills.\n\nRequirements:\n - Fear\n - Vengeance",requires={30109},sourceURL="https://www.wowhead.com/quest=30113",classes={4},npcID=57770,turnIn={mapID=25,x=0.7140000000000001,y=0.456},objectiveReference=true},
        [30116]={questID=30116,name="Sharpening Your Fangs",pickup={mapID=25,x=0.7140000000000001,y=0.456},instructions="Collect sixty INTACT Elementium Gem Clusters from original Normal/Heroic Dragon Soul bosses. Keep them unopened: loose Shadowy Gems from the previous stage do not substitute. Bring the intact clusters to Wrathion at Ravenholdt.",requires={30113},sourceURL="https://www.wowhead.com/quest=30116",classes={4},npcID=57777,turnIn={mapID=25,x=0.7140000000000001,y=0.456},objective={mapID=71,x=0.644,y=0.5}},
        [30118]={questID=30118,name="Patricide",pickup={mapID=25,x=0.7140000000000001,y=0.456},instructions="Accept Patricide from Wrathion BEFORE defeating Madness of Deathwing in original Normal/Heroic Dragon Soul. Complete the raid and loot Deathwing's jaw fragment from its final reward, then return to Wrathion at Ravenholdt for the legendary daggers. The raid marker is its entrance/starting temple; the active tracker follows the final encounter.",requires={30116},sourceURL="https://www.wowhead.com/quest=30118",classes={4},npcID=57777,turnIn={mapID=25,x=0.7040000000000001,y=0.466},objective={mapID=409,x=0.5,y=0.596},objectiveReference=true},
