--[====[
Preserved inactive research: Data/Expansions/Cataclysm/QuestRoutes.lua
This material is retained for reference and does not register character quest routes.

-- Cataclysm collection placement. Every quest, criterion and map is Retail.
local _,TDP=...
local guides,routes=TDP.CollectionWalkthroughs,TDP.CollectionQuestRoutes
local data=TDP.CataclysmQuestData
local function point(mapID,x,y) return {mapID=mapID,x=x/100,y=y/100} end
local function step(id,overrides)
    local original=data.quests[id]
    if not original then return nil end
    local copy={}
    for key,value in pairs(original) do copy[key]=value end
    for key,value in pairs(overrides or {}) do copy[key]=value end
    return copy
end
local function define(key,name,quests,options)
    local route=options or {}
    route.key,route.name,route.quests,route.version=key,name,quests,1
    route.reviewedAt,route.sourceRevision=data.reviewedAt,data.revision
    routes[key]=route
    return route
end
local function sameList(a,b)
    if #(a or {})~=#(b or {}) then return false end
    for i,value in ipairs(a or {}) do if value~=b[i] then return false end end
    return true
end
local function sameEligibility(a,b)
    return a and b and a.faction==b.faction and sameList(a.races,b.races) and sameList(a.classes,b.classes)
end
local function register(key,name,ends,options)
    local quests,seen,visiting={},{},{}
    local function visit(id)
        if seen[id] or visiting[id] then return end
        local quest=data.quests[id]
        if not quest or quest.daily or quest.repeatable then return end
        visiting[id]=true
        for _,previous in ipairs(quest.requires or {}) do visit(previous) end
        for _,previous in ipairs(quest.requiresAccepted or {}) do visit(previous) end
        visiting[id],seen[id]=nil,true
        -- Equivalent handoffs count once. Keep distinct faction/race branches
        -- so eligibility never hides the only usable version on this player.
        for _,alias in ipairs(quest.altQuests or {}) do
            if sameEligibility(quest,data.quests[alias]) then seen[alias]=true end
        end
        quests[#quests+1]=quest
        -- Include the internal vehicle story anywhere its present-day parent
        -- is needed, including chapters whose own criterion is still pending
        -- after a different character has already credited the vision chapter.
        for _,ending in ipairs(quest.childQuestIDs or {}) do visit(ending) end
    end
    for _,id in ipairs(ends) do visit(id) end
    return define(key,name,quests,options)
end
local function attach(kind,ids,route,keepPins)
    if not route then return end
    for _,id in ipairs(ids) do
        local guide=guides[kind] and guides[kind][id]
        if guide then
            guide.questRoutes=guide.questRoutes or {}
            local exists=false
            for _,current in ipairs(guide.questRoutes) do if current.key==route.key then exists=true; break end end
            if not exists then guide.questRoutes[#guide.questRoutes+1]=route end
            if keepPins then guide.keepReferencePins=true end
        end
    end
end
local function repeating(ids,overrides)
    local result={}
    for _,id in ipairs(ids) do
        local quest=step(id,overrides)
        if quest then result[#result+1]=quest end
    end
    return result
end

-- Spending marks is character work; a completed account achievement does not
-- unlock a fresh character's vendors. Never put rotating dailies in the
-- permanent prerequisite count or require every possible daily on one day.
local markStages={}
for _,stage in ipairs({{29199,20,198,27.2,62.4},{29181,150,338,47,90.7},
    {29214,150,338,47,90.7},{29279,125,338,47,90.7},
    {29281,125,338,47,90.7},{29283,125,338,47,90.7}}) do
