local function moltenChallenge(id,ends,dailies)
    local options={accountAchievementID=id,
        after="These quests open the attempt area. Use the retained guide and actual achievement criteria for the required conversations, kills, avoidance or vehicle actions."}
    if dailies then
        options.repeatableRewards=true
        options.repeatableQuests=repeating(dailies,{requires={}})
        options.offerText="Check the offered daily at the unlocked hub and follow its current branch. This is a possible rotating offer; an unavailable quest is not a guarantee that it should be visible today. An already active relevant daily takes priority."
    end
    attach("achievements",{id},molten("cata-molten-challenge-"..id,"Molten Front challenge access",ends,options),true)
end
