    if criterion.achievementID==5718 then attach("achievements",{5489},route,true)
    elseif criterion.achievementID==5719 then attach("achievements",{5490},route,true)
    elseif criterion.achievementID==5474 or criterion.achievementID==5841 or criterion.achievementID==5842
        or criterion.achievementID==5475 or criterion.achievementID==5843 or criterion.achievementID==5844 then
